using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class MeritRewardTests
{
 internal static readonly EntityId Retainer=new("created:merit-retainer");
 internal static WorldSession Lord(){var records=new[]{NewGameWorldTests.Officer(Retainer.Value,StartTemplate.Retainer,lord:"person:nobunaga")};var setup=NewGameWorldTests.Setup(records);return new(NewGameWorld.Create(setup.World,setup.Registered,"person:nobunaga",42,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,companionPolicy:PersonalCompanions.Policy,economyPolicy:HouseSalary.Policy));}
 static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
 internal static WorldSession Worked(){var s=Lord();Good(s.ManageCompanion(new(new("request:merit-agree"),Retainer,CompanionAction.Agree,20),s.PlayerControl,s.Revision));Good(s.ManageCompanion(new(new("request:merit-inspect"),Retainer,CompanionAction.Inspect),s.PlayerControl,s.Revision));NewGameWorldTests.At(s,20);var w=s.DiagnosticSnapshot();var report=w.Companions!.Reports.Single();Good(s.Open(s.PlayerControl,new(report.Message),s.Revision));var task=w.Tasks.Single(t=>t.RequestId==w.Companions.Orders.Single(q=>q.Input.Id==report.Order).Task!.RequestId);Good(s.ManageMerit(new(new("request:review-companion"),MeritAction.ReviewCompanion,Retainer,[task.Id],Object:new(report.Message)),s.Revision));return s;}
 static MeritInput Reward(WorldSession s,MeritRewardKind kind=MeritRewardKind.Coins,long amount=20)=>new(new("request:award/"+s.Revision),MeritAction.Grant,Retainer,MeritRewards.Records(s.DiagnosticSnapshot(),s.PlayerControl).Select(r=>r.Task).ToArray(),kind,kind==MeritRewardKind.Coins?amount:0);
 [Fact]public void PrincipalLedgerRequiresActualReportAndAssessment(){var s=Lord();Assert.Empty(MeritRewards.Records(s.DiagnosticSnapshot(),s.PlayerControl));s=Worked();Assert.NotEmpty(MeritRewards.Records(s.DiagnosticSnapshot(),s.PlayerControl));Assert.Empty(MeritRewards.View(s.DiagnosticSnapshot(),new("person:shingen")));}
 [Fact]public void PrivateCoinsAreActuallyTransferredAndCannotRewardTwice(){var s=Worked();var input=Reward(s);long before=NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl),other=NewGameWork.Balance(s.DiagnosticSnapshot(),Retainer);Good(s.ManageMerit(input,s.Revision));var w=s.DiagnosticSnapshot();Assert.Equal(before-20,NewGameWork.Balance(w,s.PlayerControl));Assert.Equal(other+20,NewGameWork.Balance(w,Retainer));Assert.All(MeritRewards.Records(w,s.PlayerControl),r=>Assert.True(r.Received));Assert.Equal(ResultCode.AlreadyAccepted,s.ManageMerit(ContractJson.Copy(input),s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.ManageMerit(Reward(s),s.Revision).Code);}
 [Fact]public void UnknownMeritCannotBeCreatedByChoosingATask(){var s=Lord();var input=new MeritInput(new("request:invented-merit"),MeritAction.Grant,Retainer,[new("task:invented")],MeritRewardKind.Coins,20);var raw=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.ManageMerit(input,s.Revision).Code);Assert.Equal(raw,ContractJson.Write(s.DiagnosticSnapshot()));}
 [Theory][InlineData(MeritRewardKind.Commendation)][InlineData(MeritRewardKind.Surname)][InlineData(MeritRewardKind.NameCharacter)]
 public void DocumentRewardDoesNotAllocateLandTroopsOrChangeIdentity(MeritRewardKind kind){var s=Worked();var before=s.DiagnosticSnapshot();var input=Reward(s,kind);Good(s.ManageMerit(input,s.Revision));var w=s.DiagnosticSnapshot();Assert.Equal(ContractJson.Write(before.LandRights),ContractJson.Write(w.LandRights));Assert.Equal(ContractJson.Write(before.Units),ContractJson.Write(w.Units));Assert.Equal(ContractJson.Write(before.ServiceBonds),ContractJson.Write(w.ServiceBonds));Assert.Contains(SocialAssets.Inventory(w,Retainer),o=>o.Kind=="commendation");if(kind!=MeritRewardKind.Commendation)Assert.NotEqual(w.Definitions.Characters.Single(c=>c.Id==Retainer).Name,MeritRewards.DisplayName(w,Retainer,Retainer));Assert.Equal(w.Definitions.Characters.Single(c=>c.Id==Retainer).Name,MeritRewards.DisplayName(w,new("person:shingen"),Retainer));}
 [Fact]public void SaveDuringRewardDeliveryContinuesWithSameFuture(){var s=Worked();var w=s.DiagnosticSnapshot();var input=Reward(s,MeritRewardKind.Commendation);w.CommitSequence++;MeritRewards.Execute(w,input,s.PlayerControl);Assert.False(MeritRewards.Records(w,s.PlayerControl).Single().Received);var a=new WorldSession(w);a.SetPaused(true);var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"merit-reward-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(a,"award",w.WorldId).Published);var host=new WorldSessionHost(Lord());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("award"),host.Current,host.Current.Revision));foreach(var x in new[]{a,host.Current})NewGameWorldTests.At(x,x.Seconds+1);Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot()),ContractJson.Write(host.Current.DiagnosticSnapshot()));Assert.True(MeritRewards.Records(a.DiagnosticSnapshot(),s.PlayerControl).Single().Received);}
 [Fact]public void ForgedDoubleRewardCannotLoad(){var s=Worked();Good(s.ManageMerit(Reward(s),s.Revision));var w=s.DiagnosticSnapshot();var e=w.Merits!.Events.Last();w.Merits=w.Merits with{Events=[..w.Merits.Events,e with{Input=e.Input with{Id=new("request:duplicated-award")}}]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
 [Fact]public void PriorSocialAssetsSaveKeepsBytesWithoutMeritModule(){var s=new WorldSession(SocialWorldTests.Start());Good(s.ManageSocialAsset(new(new("request:legacy-object"),SocialAssetAction.Buy,s.PlayerControl,SocialAssets.Catalog(s.DiagnosticSnapshot(),new("site:castle"))[0].Id),s.Revision));var raw=ContractJson.Write(s.DiagnosticSnapshot());Assert.DoesNotContain("Merits",System.Text.Encoding.UTF8.GetString(raw));Assert.Equal(raw,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(raw)).DiagnosticSnapshot()));}
 [Fact]public void UnreadReturnCannotBeReviewed(){var s=Lord();Good(s.ManageCompanion(new(new("request:unread-agree"),Retainer,CompanionAction.Agree,20),s.PlayerControl,s.Revision));Good(s.ManageCompanion(new(new("request:unread-inspect"),Retainer,CompanionAction.Inspect),s.PlayerControl,s.Revision));NewGameWorldTests.At(s,20);var w=s.DiagnosticSnapshot();var report=w.Companions!.Reports.Single();var task=w.Tasks.Single(t=>t.RequestId==w.Companions.Orders.Last().Task!.RequestId);Assert.Equal(ResultCode.NotAvailable,s.ManageMerit(new(new("request:unread-review"),MeritAction.ReviewCompanion,Retainer,[task.Id],Object:new(report.Message)),s.Revision).Code);}
 [Fact]public void GrievanceIsPrivateUntilTheActualLocalPetition(){var s=Worked();var w=s.DiagnosticSnapshot();w.ElapsedSeconds+=100*86400L;var g=Assert.Single(MeritRewards.Grievances(w,Retainer));Assert.Equal(s.PlayerControl,g.Principal);Assert.DoesNotContain(MeritRewards.Facts(w,s.PlayerControl,Retainer),f=>f.Description.Contains("上申"));w.CommitSequence++;MeritRewards.Execute(w,new(new("request:npc-grievance"),MeritAction.Petition,s.PlayerControl,g.Tasks),Retainer);Assert.Contains(MeritRewards.Facts(w,s.PlayerControl,Retainer),f=>f.Description.Contains("上申"));}
 [Fact]public void EvaluationAndRewardDoNotEraseExistingPaymentDebt(){var s=Worked();var before=ContractJson.Write(s.DiagnosticSnapshot().Debts);Good(s.ManageMerit(Reward(s),s.Revision));Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot().Debts));}

}
